/* File: style.css */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background-color: #0f172a;
}

.calculator {
    border-radius: 16px;
    background-color: #1e293b;
    padding: 24px;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
    width: 340px;
}

.calculator-screen {
    width: 100%;
    height: 70px;
    border: none;
    background-color: #0f172a;
    color: #f8fafc;
    text-align: right;
    padding: 0 16px;
    font-size: 2rem;
    border-radius: 8px;
    margin-bottom: 20px;
}

.calculator-keys {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-gap: 12px;
}

button {
    height: 60px;
    background-color: #334155;
    border: none;
    color: #f8fafc;
    font-size: 1.25rem;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
}

button:hover {
    background-color: #475569;
}

button:active {
    transform: scale(0.95);
}

.operator {
    background-color: #3b82f6;
    color: #ffffff;
}

.operator:hover {
    background-color: #2563eb;
}

.equal-sign {
    background-color: #22c55e;
    color: #ffffff;
    grid-row: span 2;
    height: 100%;
}

.equal-sign:hover {
    background-color: #16a34a;
}

.zero {
    grid-column: span 2;
}
