// File: script.js
const screen = document.getElementById('screen');

function appendValue(val) {
    screen.value += val;
}

function clearScreen() {
    screen.value = '';
}

function deleteLast() {
    screen.value = screen.value.slice(0, -1);
}

function calculateResult() {
    if (!screen.value) return;
    try {
        screen.value = Function(`'use strict'; return (${screen.value})`)();
    } catch (error) {
        screen.value = 'Error';
        setTimeout(() => clearScreen(), 1500);
    }
}

// Keyboard shortcuts support
document.addEventListener('keydown', (e) => {
    if ((e.key >= '0' && e.key <= '9') || ['+', '-', '*', '/', '.'].includes(e.key)) {
        appendValue(e.key);
    } else if (e.key === 'Enter') {
        calculateResult();
    } else if (e.key === 'Backspace') {
        deleteLast();
    } else if (e.key === 'Escape') {
        clearScreen();
    }
});
```

Ye calculator CSS Grid ke sath designed hai aur keyboard events bhi support karta hai:
- **C**: Screen clear karne ke liye.
- **DEL**: Single backspace.
- **Keyboard Shortcuts**: Numbers, enter (=), escape (clear), backspace support available hai.
